// Compliance points (screens 07-08): full text, a plain-words version, and a picture.
export function disclosures(p, L) {
  const pct = Math.round(p.clientFeePct * 100), m = p.termMonths, d = usd(p.monthlyDeposit);
  const en = L === "en";
  return [
    { id: "fee", viz: "feeTimeline", title: en ? "What it costs" : "Cuánto cuesta",
      body: en ? `The program fee is ${pct}% of the debt you enroll. It is charged only after a debt is settled and at least one payment is made on that settlement.` : `La tarifa del programa es el ${pct}% de la deuda que inscribes. Solo se cobra después de liquidar una deuda y de hacer al menos un pago de esa liquidación.`,
      plain: en ? "You pay nothing to the company until they actually settle a debt for you." : "No le pagas nada a la empresa hasta que realmente liquide una deuda por ti." },
    { id: "timing", viz: "months", title: en ? "How long it takes" : "Cuánto tiempo toma",
      body: en ? `Your estimated program length is ${m} months. The first settlement may take several months while your account builds up.` : `La duración estimada de tu programa es de ${m} meses. La primera liquidación puede tardar varios meses mientras se acumula tu cuenta.`,
      plain: en ? `Think of it as a ${m}-month plan. The first result usually takes a few months.` : `Piénsalo como un plan de ${m} meses. El primer resultado suele tardar unos meses.` },
    { id: "estimate", viz: "range", title: en ? "Savings are an estimate" : "Los ahorros son una estimación",
      body: en ? `The savings shown are not guaranteed. Results depend on your creditors and on keeping up your ${d} deposit.` : `Los ahorros que mostramos no están garantizados. Los resultados dependen de tus acreedores y de que mantengas tu depósito de ${d}.`,
      plain: en ? "We can't promise a number. It depends on your creditors and on you making deposits." : "No podemos prometer una cifra. Depende de tus acreedores y de que hagas tus depósitos." },
    { id: "account", viz: "moneyFlow", title: en ? "Your money, your account" : "Tu dinero, tu cuenta",
      body: en ? "Your deposits go into a dedicated account in your name. You own it and can withdraw at any time, less any account fees." : "Tus depósitos van a una cuenta dedicada a tu nombre. Es tuya y puedes retirar tu dinero cuando quieras, menos cualquier cargo de la cuenta.",
      plain: en ? "The money you save stays yours. You can take it out whenever you want." : "El dinero que ahorras sigue siendo tuyo. Puedes sacarlo cuando quieras." },
  ];
}
